/**
 * Turn a string into a URL slug: lowercase, runs of non-alphanumerics become a
 * single hyphen, no leading or trailing hyphens.
 *
 * options.maxLength: cut the slug to at most this many characters, at a word
 * boundary (last hyphen within the limit). If the first word alone exceeds the
 * limit, the word itself is cut.
 */
export function slugify(input, options = {}) {
  const slug = String(input)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  const maxLength = options && options.maxLength;
  if (maxLength == null || slug.length <= maxLength) return slug;

  const limit = Math.max(0, Math.floor(maxLength));
  let cut = slug.slice(0, limit);
  // If the next char is a hyphen, the cut already ends on a word boundary.
  if (slug[limit] !== '-') {
    const lastHyphen = cut.lastIndexOf('-');
    if (lastHyphen > 0) cut = cut.slice(0, lastHyphen);
  }
  return cut.replace(/-+$/, '');
}

